macro_rules! handle_options {
    () => {
        # [doc = " Process command line options. Emits messages as appropriate. If compilation"] # [doc = " should continue, returns a getopts::Matches object parsed from args,"] # [doc = " otherwise returns `None`."] # [doc = ""] # [doc = " The compiler's handling of options is a little complicated as it ties into"] # [doc = " our stability story. The current intention of each compiler option is to"] # [doc = " have one of two modes:"] # [doc = ""] # [doc = " 1. An option is stable and can be used everywhere."] # [doc = " 2. An option is unstable, and can only be used on nightly."] # [doc = ""] # [doc = " Like unstable library and language features, however, unstable options have"] # [doc = " always required a form of \"opt in\" to indicate that you're using them. This"] # [doc = " provides the easy ability to scan a code base to check to see if anything"] # [doc = " unstable is being used. Currently, this \"opt in\" is the `-Z` \"zed\" flag."] # [doc = ""] # [doc = " All options behind `-Z` are considered unstable by default. Other top-level"] # [doc = " options can also be considered unstable, and they were unlocked through the"] # [doc = " `-Z unstable-options` flag. Note that `-Z` remains to be the root of"] # [doc = " instability in both cases, though."] # [doc = ""] # [doc = " So with all that in mind, the comments below have some more detail about the"] # [doc = " contortions done here to get things to work out correctly."] # [doc = ""] # [doc = " This does not need to be `pub` for rustc itself, but @chaosite needs it to"] # [doc = " be public when using rustc as a library, see"] # [doc = " <https://github.com/rust-lang/rust/commit/2b4c33817a5aaecabf4c6598d41e190080ec119e>"] pub fn handle_options (early_dcx : & EarlyDiagCtxt , args : & [String]) -> Option < getopts :: Matches > { let mut options = getopts :: Options :: new () ; let optgroups = config :: rustc_optgroups () ; for option in & optgroups { option . apply (& mut options) ; } let matches = options . parse (args) . unwrap_or_else (| e | { let msg : Option < String > = match e { getopts :: Fail :: UnrecognizedOption (ref opt) => CG_OPTIONS . iter () . map (| opt_desc | ('C' , opt_desc . name ())) . chain (Z_OPTIONS . iter () . map (| opt_desc | ('Z' , opt_desc . name ()))) . find (| & (_ , name) | * opt == name . replace ('_' , "-")) . map (| (flag , _) | format ! ("{e}. Did you mean `-{flag} {opt}`?")) , getopts :: Fail :: ArgumentMissing (ref opt) => { optgroups . iter () . find (| option | option . name == opt) . map (| option | { let mut options = getopts :: Options :: new () ; option . apply (& mut options) ; options . usage_with_format (| it | { it . fold (format ! ("{e}\nUsage:") , | a , b | a + "\n" + & b) }) }) } _ => None , } ; early_dcx . early_fatal (msg . unwrap_or_else (| | e . to_string ())) ; }) ; nightly_options :: check_nightly_options (early_dcx , & matches , & config :: rustc_optgroups ()) ; if args . is_empty () || matches . opt_present ("h") || matches . opt_present ("help") { let unstable_enabled = nightly_options :: is_unstable_enabled (& matches) ; let nightly_build = nightly_options :: match_is_nightly_build (& matches) ; usage (matches . opt_present ("verbose") , unstable_enabled , nightly_build) ; return None ; } if describe_flag_categories (early_dcx , & matches) { return None ; } if matches . opt_present ("version") { version ! (early_dcx , "rustc" , & matches) ; return None ; } warn_on_confusing_output_filename_flag (early_dcx , & matches , args) ; Some (matches) }
    };
}

handle_options!();